"""Transformations, isometries, superpositions and the first two exercises of chapter XIV."""
import argparse
import json
from coordinate_curves import graph
from triangle_sine_area import area
from vector_scaling import BOOK, ROOT

OUT = ROOT/'geometry-course/textbook/data/plane-isometries.json'
PRIME = '′'


def schematic(title, points, edges):
    low = min(p[1] for p in points.values())-1.25
    left = min(p[0] for p in points.values())
    return graph(title, {**points, 'U':(left,low),'W':(left+1,low)}, edges=[*edges,('U','W')])


def reflect(title, kind, points, edges=(), join=True):
    """A vertical mirror or a half-turn; the indicated points get their actual images."""
    points = dict(points)
    mirror = kind == 'axis'
    image = {k+PRIME:(-x,y if mirror else -y) for k,(x,y) in points.items()}
    transformed = [(a+PRIME,b+PRIME) for a,b in edges]
    connectors = [(k,k+PRIME) for k in points] if join else []
    coord = {**points,**image,'T':(0,0)}
    if mirror:
        lo=min(-1,*[p[1] for p in points.values()])-1
        hi=max(1,*[p[1] for p in points.values()])+1
        coord.update(K=(0,lo),L=(0,hi))
        connectors += [('K','L')]
    return schematic(title,coord,[*edges,*transformed,*connectors])


def candidate(title, height):
    points = {'A':(-2,0),'B':(2,0),'C':(0,height),'M':(1,2),'N':(1,-2)}
    return schematic(title,points,[('A','B'),('A','C'),('B','C'),
                                  ('A','M'),('A','N'),('B','M'),('B','N'),('C','M'),('C','N')])


def card(n, part, pages, question, proof, hint, steps, views, probes, caption, title=None):
    c = area(n,part,pages,question,proof,hint,steps,views,probes,
             title=title,refs=[122,123] if n != 124 else [123])
    c['source']['chapter']='XIV'
    c['review']['reviewer']='Атанасян и др., Геометрия 7–9, издание 2023 года, §1 главы XIV. Сверены исходные пункты 122–124 и оба подпункта №1240–1241 на с. 313–318.'
    c['visualization']['caption']=c['visualization']['model']['description']=caption+' UW — единица длины.'
    if not title:
        c['answer']['prompt']='Напиши доказательство для всей прямой. Объясни, как найти прообраз произвольно выбранной точки её образа.'
        c['help'][1]['text']=hint
    return c


