def line_card(number, part, question, proof, hint, steps, specs, probes, caption):
    drawings=[reflect(label,kind,dict(zip('AB',pair)),[('A','B')]) for label,kind,pair in specs]
    return card(number,part,[318],question,proof,hint,steps,drawings,probes,caption)


